package com.ccb.testmanagement.service;

// 关键逻辑：文件输入输出在模块内限制格式、大小和字段边界；异常内容不能绕过既有业务校验。

import org.apache.poi.xwpf.usermodel.XWPFDocument;
import org.apache.poi.xwpf.usermodel.XWPFParagraph;
import org.springframework.stereotype.Service;
import java.io.ByteArrayOutputStream;
import java.nio.charset.StandardCharsets;
import java.util.*;

/** 报告导出使用真正的 OOXML Word；PDF 使用 Adobe CJK Type0 字体，避免中文降级为问号。 */
@Service public class TestReportDocumentService {
 public byte[] docx(Map<String,Object> detail){try(XWPFDocument doc=new XWPFDocument();ByteArrayOutputStream out=new ByteArrayOutputStream()){title(doc,"测试报告："+String.valueOf(((Map<?,?>)detail.get("report")).get("report_name")));Map<?,?> facts=(Map<?,?>)detail.get("snapshot");for(String k:FACTS){line(doc,label(k)+"："+String.valueOf(facts.get(k)==null?"0":facts.get(k)));}for(String code:CHAPTERS){title(doc,chapter(code));line(doc,chapterText(code,facts,supplementByChapter(detail)));}doc.write(out);return out.toByteArray();}catch(Exception e){throw new IllegalStateException("Word 导出失败",e);}}
 public byte[] pdf(Map<String,Object> detail){List<String> lines=new ArrayList<>();Map<?,?> report=(Map<?,?>)detail.get("report");lines.add("测试报告："+report.get("report_name"));Map<?,?> facts=(Map<?,?>)detail.get("snapshot");for(String key:FACTS)lines.add(label(key)+"："+String.valueOf(facts.get(key)==null?"0":facts.get(key)));Map<String,String> supplements=supplementByChapter(detail);for(String code:CHAPTERS){lines.add(chapter(code));lines.add(chapterText(code,facts,supplements));}StringBuilder content=new StringBuilder("BT /F1 11 Tf 50 790 Td ");for(String line:lines){content.append("<").append(utf16be(line)).append("> Tj 0 -16 Td ");}content.append("ET");String body=content.toString();List<String> objects=List.of("<< /Type /Catalog /Pages 2 0 R >>","<< /Type /Pages /Kids [3 0 R] /Count 1 >>","<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 5 0 R >> >> /Contents 4 0 R >>","<< /Length "+body.getBytes(StandardCharsets.ISO_8859_1).length+" >>\nstream\n"+body+"\nendstream","<< /Type /Font /Subtype /Type0 /BaseFont /STSong-Light /Encoding /UniGB-UCS2-H /DescendantFonts [6 0 R] >>","<< /Type /Font /Subtype /CIDFontType0 /BaseFont /STSong-Light /CIDSystemInfo << /Registry (Adobe) /Ordering (GB1) /Supplement 2 >> >>");StringBuilder out=new StringBuilder("%PDF-1.4\n");List<Integer> pos=new ArrayList<>();for(int i=0;i<objects.size();i++){pos.add(out.length());out.append(i+1).append(" 0 obj\n").append(objects.get(i)).append("\nendobj\n");}int start=out.length();out.append("xref\n0 ").append(objects.size()+1).append("\n0000000000 65535 f \n");for(int p:pos)out.append(String.format(Locale.ROOT,"%010d 00000 n \n",p));out.append("trailer << /Size ").append(objects.size()+1).append(" /Root 1 0 R >>\nstartxref\n").append(start).append("\n%%EOF");return out.toString().getBytes(StandardCharsets.ISO_8859_1);}
 private static final List<String> FACTS=List.of("effective_case_total","invalid_case_total","execution_total","execution_unexecuted","execution_in_progress","execution_success","execution_failed","execution_blocked","execution_rate","case_success_rate","executed_case_success_rate","defect_total","defect_open","defect_density","defect_repair_rate");
 private static final List<String> CHAPTERS=List.of("OVERVIEW","ENVIRONMENT_CONFIG","SCOPE_STRATEGY","EXECUTION_PROGRESS","DEFECT_ANALYSIS","QUALITY_ASSESSMENT","RISKS_ISSUES","CONCLUSION_RECOMMENDATION");
 private static final String CHAPTER_CONTENT_MARKER="<!-- tm-report-chapter-content-v2 -->";
 private Map<String,String> supplementByChapter(Map<String,Object> detail){Map<String,String> result=new HashMap<>();for(Map<?,?> item:(List<Map<?,?>>)detail.getOrDefault("supplements",List.of()))result.put(String.valueOf(item.get("chapter_code")),String.valueOf(item.get("content_html")==null?"":item.get("content_html")));return result;}
 private String chapterText(String code,Map<?,?> facts,Map<String,String> supplements){String saved=supplements.getOrDefault(code,"");if(saved.startsWith(CHAPTER_CONTENT_MARKER))return strip(saved.substring(CHAPTER_CONTENT_MARKER.length()));String generated=narrative(code,facts);return saved.isBlank()?generated:generated+" 补充说明："+strip(saved);}
 private void title(XWPFDocument d,String s){XWPFParagraph p=d.createParagraph();p.createRun().setBold(true);p.createRun().setText(s);}private void line(XWPFDocument d,String s){d.createParagraph().createRun().setText(s);}private String strip(String s){return s.replaceAll("<[^>]*>"," ").replace("&nbsp;"," ").trim();}private String utf16be(String value){StringBuilder result=new StringBuilder("FEFF");for(char character:value.toCharArray())result.append(String.format(Locale.ROOT,"%04X",(int)character));return result.toString();}private String fact(Map<?,?> facts,String key){return String.valueOf(facts.get(key)==null?"0":facts.get(key));}private double number(Map<?,?> facts,String key){try{return Double.parseDouble(fact(facts,key));}catch(NumberFormatException e){return 0;}}private String percentage(double value){return String.format(Locale.ROOT,"%.2f%%",value);}private String narrative(String code,Map<?,?> facts){double effective=number(facts,"effective_case_total"),total=number(facts,"case_total"),executed=number(facts,"execution_total"),unexecuted=number(facts,"execution_unexecuted"),inProgress=number(facts,"execution_in_progress"),failed=number(facts,"execution_failed"),blocked=number(facts,"execution_blocked"),open=number(facts,"defect_open"),defects=number(facts,"defect_total"),severe=number(facts,"severe_defect_count");return switch(code){case "OVERVIEW"->"当前范围覆盖 "+fact(facts,"scope_total")+" 个测试范围和 "+fact(facts,"case_total")+" 条案例，已执行 "+fact(facts,"execution_total")+" 条，执行率 "+percentage(number(facts,"execution_rate"))+"；待完成或确认 "+Math.round(unexecuted+inProgress)+" 条。";case "ENVIRONMENT_CONFIG"->"当前范围已形成 "+Math.round(executed)+" 条可用于质量判断的执行结果；"+(inProgress>0?"仍有 "+Math.round(inProgress)+" 条案例执行中，应持续保障环境和依赖条件稳定。":"当前未遗留执行中案例，可支撑后续复测与收尾。");case "SCOPE_STRATEGY"->"有效案例 "+Math.round(effective)+" 条，占纳入案例的 "+percentage(total>0?effective*100/total:0)+"；当前范围已覆盖 "+fact(facts,"scope_total")+" 个测试范围，具备开展质量评估的基础。";case "EXECUTION_PROGRESS"->"已执行案例中成功 "+fact(facts,"execution_success")+" 条，已执行案例成功率 "+percentage(number(facts,"executed_case_success_rate"))+"；失败和阻塞合计 "+Math.round(failed+blocked)+" 条，应优先定位原因并推进复测。";case "DEFECT_ANALYSIS"->"当前发现缺陷 "+Math.round(defects)+" 个，未关闭 "+Math.round(open)+" 个，占比 "+percentage(defects>0?open*100/defects:0)+"；"+(severe>0?"存在 "+Math.round(severe)+" 个严重缺陷，应按最高优先级处置。":"当前无严重缺陷，重点应放在未关闭问题的按期收敛。");case "QUALITY_ASSESSMENT"->"质量结论应以已启用指标的实际结果为依据；建议优先处理风险和不达标指标，再复核整体质量状态。";case "RISKS_ISSUES"->"当前风险主要集中在失败案例 "+Math.round(failed)+" 条、阻塞案例 "+Math.round(blocked)+" 条和未关闭缺陷 "+Math.round(open)+" 个；建议明确责任、时限和复测闭环。";case "CONCLUSION_RECOMMENDATION"->"建议优先完成 "+Math.round(failed+blocked)+" 条失败或阻塞案例及 "+Math.round(open)+" 个未关闭缺陷的处置，复测确认后再更新质量结论。";default->"";};}private String label(String key){return switch(key){case "effective_case_total"->"有效案例数";case "invalid_case_total"->"无效案例数";case "execution_total"->"已执行案例数";case "execution_unexecuted"->"未执行案例数";case "execution_in_progress"->"执行中案例数";case "execution_success"->"成功案例数";case "execution_failed"->"失败案例数";case "execution_blocked"->"阻塞案例数";case "execution_rate"->"执行率";case "case_success_rate"->"案例成功率";case "executed_case_success_rate"->"已执行案例成功率";case "defect_total"->"缺陷总数";case "defect_open"->"未关闭缺陷数";case "severe_defect_count"->"严重缺陷数";case "defect_density"->"缺陷密度";case "defect_repair_rate"->"缺陷修复率";default->key;};}private String chapter(String code){return switch(code){case "OVERVIEW"->"报告概述";case "ENVIRONMENT_CONFIG"->"测试环境与配置";case "SCOPE_STRATEGY"->"测试范围与策略";case "EXECUTION_PROGRESS"->"测试执行与进度";case "DEFECT_ANALYSIS"->"缺陷分析";case "QUALITY_ASSESSMENT"->"质量评估";case "RISKS_ISSUES"->"风险与问题";case "CONCLUSION_RECOMMENDATION"->"结论与建议";case "SCOPE_STAT"->"测试范围统计";case "EXECUTION_STAT"->"案例执行统计";case "DEFECT_STAT"->"缺陷统计";case "QUALITY_STAT"->"质量阈值判定";case "SCOPE_DETAIL"->"测试范围明细";case "EXECUTION_DETAIL"->"案例执行明细";case "DEFECT_DETAIL"->"缺陷明细";default->code;};}
}
